// Shared account entry and server-delivered enquiries for the Mac Mini deployment.
function connect(){for(const a of document.querySelectorAll('a[href="#/signin"],a[href="#/signup"],a[href="#/workspace"]'))a.href='/account/';if(['#/signin','#/signup','#/workspace'].includes(location.hash)){location.replace('/account/');return;}const form=document.querySelector('#contact-form');if(!form)return;const notice=document.querySelector('.form-layout .notice');if(notice)notice.textContent='Send your requirements to the ZARBITZ team. We will reply using your contact details.';const fine=form.querySelector('.fine');if(fine)fine.textContent='Your enquiry will be stored and sent to the ZARBITZ team.';const button=form.querySelector('[type="submit"]');button.textContent='Submit enquiry';form.onsubmit=async e=>{e.preventDefault();button.disabled=true;const result=document.querySelector('#form-result');try{const response=await fetch('/api/enquiries',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(Object.fromEntries(new FormData(form)))});const data=await response.json();if(!response.ok)throw Error(data.error||'Submission failed');result.textContent=data.message;form.reset();}catch(err){result.textContent='Could not submit. Please try again.';}finally{button.disabled=false;}};}
window.addEventListener('hashchange',()=>setTimeout(connect,0));setTimeout(connect,0);
